async page => {
  const DIR = "~/AppData/Local/Temp/claude/D--GitHub-public-sandbox-mesa-redonda/54696a17-103e-4574-ae83-ca9d8ec05d2b/scratchpad/capturas/";
  // La respuesta que "manda el modelo": texto, un bloque java, un bloque sin
  // lenguaje (se detecta), una linea vacia dentro del codigo y HTML hostil
  // dentro de un bloque, que tiene que verse como texto.
  const RESPUESTA =
    "ValidadorDeCitas recorre las citas del texto y marca las que quedan fuera de 1..k [1]:\n" +
    "```java\n" +
    "static Resultado validar(String texto, int k) {\n" +
    "  List<Long> fuera = new ArrayList<>();\n" +
    "  Matcher m = CITA.matcher(sinCodigo(texto));\n" +
    "\n" +
    "  while (m.find()) {\n" +
    "    long n = Long.parseLong(m.group(1).trim()); // \"[n]\"\n" +
    "    if (n < 1 || n > k) fuera.add(n);\n" +
    "  }\n" +
    "  return new Resultado(fuera);\n" +
    "}\n" +
    "```\n" +
    "Para ver las advertencias guardadas:\n" +
    "```\n" +
    "SELECT q.question, q.advertencias\n" +
    "  FROM query_log q\n" +
    " WHERE q.advertencias IS NOT NULL;\n" +
    "```\n" +
    "Y un bloque con HTML que no se ejecuta:\n" +
    "```html\n" +
    "<img src=x onerror=\"window.__xss=1\"><b>no negrita</b>\n" +
    "```\n" +
    "Listo.";
  const PAUSA_EN = RESPUESTA.indexOf("  while");

  await page.context().grantPermissions(["clipboard-read", "clipboard-write"], { origin: "http://localhost:8080" });
  await page.setViewportSize({ width: 1180, height: 1300 });
  await page.emulateMedia({ colorScheme: "light" });
  await page.addInitScript(({ respuesta, pausaEn }) => {
    const Real = window.EventSource;
    window.__fase = "inicio";
    window.EventSource = function (url) {
      if (!String(url).startsWith("/api/chat?")) {
        return new Real(url);
      }
      const listeners = {};
      const fuente = {
        url: url,
        readyState: 1,
        onerror: null,
        addEventListener(tipo, fn) { (listeners[tipo] = listeners[tipo] || []).push(fn); },
        close() { this.cerrada = true; },
      };
      const emitir = (tipo, data) => {
        if (!fuente.cerrada) (listeners[tipo] || []).forEach((fn) => fn({ data: data }));
      };
      // Trozos de 3 caracteres: las cercas ``` llegan partidas entre tokens.
      const trozos = respuesta.match(/[\s\S]{1,3}/g);
      let i = 0;
      let enviado = 0;
      const siguiente = () => {
        if (i >= trozos.length) {
          emitir("fin", "");
          window.__fase = "fin";
          return;
        }
        emitir("token", JSON.stringify(trozos[i]));
        enviado += trozos[i].length;
        i++;
        if (window.__fase === "inicio" && enviado >= pausaEn) {
          window.__fase = "pausa";
          window.__seguir = () => { window.__fase = "siguiendo"; setTimeout(siguiente, 10); };
          return;
        }
        setTimeout(siguiente, 8);
      };
      setTimeout(() => {
        emitir("citas", JSON.stringify([{ titulo: "ValidadorDeCitas.java", uri: "repo://orquestacion/ValidadorDeCitas.java", extracto: "static Resultado validar" }]));
        siguiente();
      }, 50);
      return fuente;
    };
  }, { respuesta: RESPUESTA, pausaEn: PAUSA_EN });
  await page.route("**/api/preview", (r) => r.fulfill({ status: 200, contentType: "application/json", body: "[]" }));

  await page.goto("http://localhost:8080/");
  await page.fill("#pregunta", "¿Cómo detecta el orquestador una cita [n] fuera de rango?");
  await page.press("#pregunta", "Enter");

  await page.waitForFunction(() => window.__fase === "pausa");
  const turno = page.locator(".turno").last();
  const enStreaming = await turno.evaluate((t) => {
    const b = [...t.querySelectorAll(".bloque-codigo")];
    return { bloques: b.length, copiarOculto: b.map((x) => x.querySelector(".boton-copiar-codigo").hidden),
      rotulo: b.map((x) => x.querySelector(".acciones-codigo").dataset.lenguaje) };
  });
  await turno.screenshot({ path: DIR + "1-streaming-claro.png" });
  await page.evaluate(() => window.__seguir());
  await page.waitForFunction(() => window.__fase === "fin");
  await page.waitForTimeout(300);

  const final = await turno.evaluate((t) => {
    const r = t.querySelector(".turno-respuesta");
    const b = [...r.querySelectorAll(".bloque-codigo")];
    const linea = r.querySelector(".linea");
    return {
      bloques: b.length,
      rotulos: b.map((x) => x.querySelector(".acciones-codigo").dataset.lenguaje),
      copiarOculto: b.map((x) => x.querySelector(".boton-copiar-codigo").hidden),
      lineasJava: b[0].querySelectorAll(".linea").length,
      resaltadoJava: b[0].querySelectorAll("code span[class^=hljs-]").length,
      userSelectNumero: getComputedStyle(linea, "::before").userSelect,
      numeroPrimeraLinea: getComputedStyle(linea, "::before").content,
      imgInyectada: r.querySelectorAll("img, b").length,
      xss: window.__xss || 0,
      innerText: r.innerText,
    };
  });
  await turno.screenshot({ path: DIR + "2-final-claro.png" });

  await turno.locator(".boton-copiar-codigo").first().click();
  await page.waitForTimeout(200);
  const copiado = await page.evaluate(() => navigator.clipboard.readText());
  const estadoCopiado = await turno.locator(".boton-copiar-codigo").first().evaluate((x) =>
    ({ clase: x.className, aria: x.getAttribute("aria-label"), after: getComputedStyle(x, "::after").content }));
  await turno.locator(".bloque-codigo").first().screenshot({ path: DIR + "3-copiado-claro.png" });
  await page.waitForTimeout(2300);
  const trasDosSegundos = await turno.locator(".boton-copiar-codigo").first().evaluate((x) => x.className);

  await page.emulateMedia({ colorScheme: "dark" });
  await page.waitForTimeout(200);
  await turno.screenshot({ path: DIR + "4-final-oscuro.png" });
  const fondoOscuro = await turno.locator(".bloque-codigo").first().evaluate((x) => getComputedStyle(x).backgroundColor);

  // Historial: recargar y abrir la conversacion guardada en IndexedDB.
  await page.reload();
  await page.locator(".item-conversacion").first().click();
  await page.waitForSelector(".turno .bloque-codigo");
  const restaurado = await page.locator(".turno").last().evaluate((t) => ({
    bloques: t.querySelectorAll(".bloque-codigo").length,
    copiarOculto: [...t.querySelectorAll(".boton-copiar-codigo")].map((x) => x.hidden),
    innerText: t.querySelector(".turno-respuesta").innerText,
  }));
  await page.locator(".turno").last().screenshot({ path: DIR + "5-historial-oscuro.png" });

  return JSON.stringify({
    enStreaming, final, copiado, copiaExacta: copiado === RESPUESTA.split("```java\n")[1].split("\n```")[0],
    estadoCopiado, trasDosSegundos, fondoOscuro,
    restaurado: { ...restaurado, mismoInnerText: restaurado.innerText === final.innerText },
  }, null, 2);
}

