async page => {
  await page.addInitScript(() => {
    const Real = window.EventSource;
    window.EventSource = function (url) {
      if (!String(url).startsWith("/api/chat?")) return new Real(url);
      const l = {};
      const f = { addEventListener(t, fn) { (l[t] = l[t] || []).push(fn); }, close() {} };
      const emitir = (t, d) => (l[t] || []).forEach((fn) => fn({ data: d }));
      setTimeout(() => {
        emitir("citas", "[]");
        emitir("token", JSON.stringify("Texto\n```js\nconst a = 1;\n```\nFin"));
        emitir("fin", "");
        window.__fin = true;
      }, 50);
      return f;
    };
  });
  await page.route("**/vendor/highlight/highlight.min.js", (r) => r.fulfill({ status: 404, body: "" }));
  await page.route("**/api/preview", (r) => r.fulfill({ status: 200, contentType: "application/json", body: "[]" }));
  await page.goto("http://localhost:8080/");
  await page.fill("#pregunta", "respaldo sin highlight");
  await page.press("#pregunta", "Enter");
  await page.waitForFunction(() => window.__fin === true);
  return await page.locator(".turno").last().locator(".turno-respuesta").innerText();
}

